import{_ as s,l,o as e,c as i,v as t,p as n,x as r,d as p,i as c,S as E}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"顺序与因果一致性","description":"","frontmatter":{"title":"顺序与因果一致性","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sequential-causal-consistency.md","filePath":"cs/sequential-causal-consistency.md","lastUpdated":1789023840000}'),d={name:"cs/sequential-causal-consistency.md"};function h(u,a,A,_,m,B){const o=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="顺序与因果一致性" tabindex="-1">顺序与因果一致性 <a class="header-anchor" href="#顺序与因果一致性" aria-label="Permalink to &quot;顺序与因果一致性&quot;">​</a></h1><div class="epigraph"><p>顺序一致要有一个全局操作序，符合每进程程序序，但不须符合实时。因果一致只要求 happened-before 的写被看到的顺序不颠倒。</p><footer>—— 据 Lamport, How to Make a Multiprocessor Computer That Correctly Executes Multiprocess Programs, IEEE TC 1979；Ahamad et al., Causal Memory, 1995 整理</footer></div><p>上一课<a href="/cs/linearizability">线性一致性</a>把实时也算进顺序。缺口是<strong>更便宜的档</strong>：多核与广域复制常常放弃实时，只保留程序序或因果。本课不重画线性化点。后课最终一致还要再放弃「何时看到」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Lamport 顺序一致：存在全体操作的全序，每处理器上的程序序是该全序的子序，读看到的是该全序下最近的写。允许：实时上 A 已返回、B 才调用，历史仍把 B 排在 A 前——只要没人在中间用程序序钉住。这比线性一致弱，比「随便缓存」强。</p><p>因果一致（Ahamad 等因果内存）：若写 \\(w_1\\to w_2\\)（<a href="/cs/vector-clocks">向量时钟</a>的偏序，含程序序与同步），则任何读不能先看到 \\(w_2\\) 再看到 \\(w_1\\) 缺席的那种颠倒。并发写可以不同副本不同序。缺口：复制要在「全局全序」和「只保因果」之间选预算。</p><p><span class="marginnote">顺序一致没有线性一致的局部性：两个顺序一致对象并排放，组合不必顺序一致。因果常用版本向量或因果广播实现。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现顺序一致：单总线、单日志、或每读拉全局屏障——贵。实现因果：写带依赖向量，读缓冲直到依赖到齐；或因果广播（Birman 等）。不要用 NTP 排序冒充因果。</p>',9)),(e(),n(E,null,{default:r(()=>[c(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20LIN%5B%22%E7%BA%BF%E6%80%A7%E4%B8%80%E8%87%B4%3A%20%E5%AE%9E%E6%97%B6%2B%E5%8E%9F%E5%AD%90%E7%82%B9%22%5D%20--%3E%20SEQ%5B%22%E9%A1%BA%E5%BA%8F%E4%B8%80%E8%87%B4%3A%20%E5%85%A8%E5%B1%80%E5%BA%8F%2B%E7%A8%8B%E5%BA%8F%E5%BA%8F%22%5D%0A%20%20SEQ%20--%3E%20CAU%5B%22%E5%9B%A0%E6%9E%9C%3A%20%E5%8F%AA%E4%BF%9D%20%E2%86%92%22%5D%0A%20%20CAU%20--%3E%20EV%5B%22%E6%9C%80%E7%BB%88%E4%B8%80%E8%87%B4%20%E5%90%8E%E8%AF%BE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>PRAM（流水线内存）更弱：只保<strong>同一进程</strong>写的顺序，跨进程写可乱。本课点名，以免和因果混称。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>多核硬件提供的是更弱的模型（store buffer），靠 fence 升到需要的档——那是体系结构课的内存模型，本课只借用「档位」语言，不重写 store buffer。分布式里：从库异步 apply 常常连因果都破（先 apply 了无依赖的新写）。要因果，复制流必须按依赖或按单日志。</p><p>线性一致 ⇒ 顺序一致 ⇒ 因果一致，逆不成立。选档是给应用的承诺：锁的互斥通常要线性一致；协作编辑的插入因果可能够；计数器最终一致可能够。</p><p>本课不把「因果一致」写成区块链的确认规则，也不写限价簿撮合序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写会话保证的六条（那是后课把因果再拆成客户端视角）。不引入 CRDT 合并。后课默认：放弃实时先落到顺序或因果；再放弃「所有人终见同一写集合的同一全序」就进最终一致。主备协议必须声明自己停在哪一档。</p><p>档位是历史集合，不是 QPS 数字。没有声明就没有正确性讨论。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>顺序一致：全局全序 + 程序序，不必实时。</li><li>因果一致：不颠倒 \\(a\\to b\\) 的写可见性；并发可分叉。</li><li>线性 ⇒ 顺序 ⇒ 因果；实现成本同向。</li><li>出处：Lamport, IEEE TC 1979；Ahamad et al., 1995。</li></ul>',10))])}const b=s(d,[["render",h]]);export{T as __pageData,b as default};
